
//////
//
// Includes
//

// C++ STL
#include <algorithm>
#include <cstddef>
#include <cstdint>
#include <memory>
#include <optional>
#include <span>
#include <vector>

// Dear ImGui
#include <imgui.h>

// GLM library
#include <glm/gtx/transform.hpp>

// SDL3 library
#include <SDL3/SDL.h>

// Embedded resources (generated by cpp-embedlib)
#include <hello-shaders.h>

// FCG Framework
#include <FCG/run.h>
#include <FCG/res.h>
#include <FCG/player.h>
#include <FCG/applet.h>
#include <FCG/applet/orbit_camera.h>
#include <FCG/Render/ellipsoid_renderer.h>
#include <FCG/Render/line_renderer.h>

// Local includes
#include <shapes/convex_poly.h>
#include <shapes/platonic_solid.h>



//////
//
// Classes
//

/// \brief
/// 	Demo applet that renders one of several procedurally generated simple shapes, selectable and configurable via
/// 	the GUI.
///
/// The shapes are drawn with Blinn-Phong lighting by the embedded \c simple_shapes shader, using the viewing
/// transformation of the current \c fcg::RenderState (e.g. as set up by a camera applet running before this one).
/// Optional spheres mark geometric corners, with their radius specified as a percentage of the shape's circumradius.
/// Geometric and triangulated wireframes show independent pixel-width segments with optional filtered edges.
/// Triangulation diagonals are light grey and use 75% of the white face-edge width.
class SimpleShapesApplet : public fcg::Applet
{
public:

	////
	// Types

	/// Representation selected independently of the shape and corner markers.
	enum class DisplayMode
	{
		/// The filled, lit triangle mesh.
		Solid,

		/// Unique geometric face boundaries.
		Wireframe,

		/// White geometric face boundaries with thinner, light-grey triangulation diagonals.
		TriangulatedWireframe
	};


	////
	// Object construction/destruction

	/// Constructs the applet with one instance of each simple shape. The platonic solid is selected initially.
	SimpleShapesApplet()
		: shapes{std::make_unique<ConvexPolygon>(), std::make_unique<PlatonicSolid>()}
	{}

	/// Releases the graphics pipeline created by \c recreatePipelines. The device passed to \c init must still be
	/// alive.
	~SimpleShapesApplet() override {
		if (m_device != nullptr && m_pipeline != nullptr)
			SDL_ReleaseGPUGraphicsPipeline(m_device->handle(), m_pipeline);
	}


	////
	// Interface: fcg::Applet

	/// \brief Returns the display name of this applet.
	///
	/// \return The string <tt>"Simple Shapes"</tt>.
	[[nodiscard]] auto name () const -> const std::string& override {
		const static std::string name = "Simple Shapes";
		return name;
	}

	/// \brief Retain the device and create the corner and wireframe collections.
	///
	/// \param device The device to create the pipeline on. It must outlive the applet.
	/// \param player The player providing the main render target's color format.
	void init (fcg::Device &device, fcg::Player &player) override {
		m_device = &device;
		cornerAttributes = std::make_unique<fcg::PrimitiveAttributes>(device);
		wireAttributes = std::make_unique<fcg::PrimitiveAttributes>(device);
		wireEdges = std::make_unique<fcg::PrimitiveConnectivity>(device);
	}

	/// \brief Replace mesh, corner and line pipelines for the player's effective target.
	///
	/// Draws indexed triangle lists and corner spheres with depth testing and writing. Failures are logged and
	/// disable the affected drawing.
	///
	/// \param device The application's GPU device, which outlives the applet.
	/// \param player The player providing the effective scene render target.
	void recreatePipelines (fcg::Device &device, fcg::Player &player) override
	{
		if (m_pipeline)
			SDL_ReleaseGPUGraphicsPipeline(m_device->handle(), m_pipeline);
		m_pipeline = nullptr;

		// Create the corner renderer for the effective scene target
		cornerRenderer.reset();
		auto renderer = fcg::EllipsoidRenderer::create(player);
		if (renderer)
			cornerRenderer.emplace(std::move(*renderer));
		else
			SDL_LogError(SDL_LOG_CATEGORY_APPLICATION, "Creating corner renderer: %s", renderer.error().message.c_str());

		// Blend filtered lines against the scene without making rear edges occlude one another
		lineRenderer.reset();
		auto lines = fcg::LineRenderer::create(player, {.depthWrite = false, .alphaBlending = true});
		if (lines) {
			lineRenderer.emplace(std::move(*lines));
			applyLineStyle();
		}
		else
			SDL_LogError(SDL_LOG_CATEGORY_APPLICATION, "Creating wireframe renderer: %s", lines.error().message.c_str());

		// Load the embedded app shader stages.
		auto shader = fcg::res::shader(res::shaders::FS, "simple_shapes");
		if (!shader) {
			SDL_LogCritical(SDL_LOG_CATEGORY_ERROR, "Embedded app shader 'simple_shapes' not found");
			return;
		}
		auto vertex = shader->stage(fcg::ShaderStage::VERTEX);
		auto fragment = shader->stage(fcg::ShaderStage::FRAGMENT);
		if (!vertex || !fragment) {
			SDL_LogCritical(SDL_LOG_CATEGORY_ERROR, "Embedded app shader 'simple_shapes' is missing a graphics stage");
			return;
		}

		auto *vertexShader = device.createShader(fcg::ShaderStage::VERTEX, vertex->spirv, 1);
		auto *fragmentShader = device.createShader(fcg::ShaderStage::FRAGMENT, fragment->spirv, 0);
		if (!vertexShader || !fragmentShader) {
			if (vertexShader)
				SDL_ReleaseGPUShader(device.handle(), vertexShader);
			if (fragmentShader)
				SDL_ReleaseGPUShader(device.handle(), fragmentShader);
			return; // createShader already logged the error.
		}

		// Vertex layout: interleaved position + normal, both vec4.
		SDL_GPUVertexBufferDescription vertexBufferDesc {};
		vertexBufferDesc.slot = 0;
		vertexBufferDesc.pitch = sizeof(SimpleShape::Vertex);
		vertexBufferDesc.input_rate = SDL_GPU_VERTEXINPUTRATE_VERTEX;

		SDL_GPUVertexAttribute vertexAttributes[2] {};
		vertexAttributes[0].location = 0;
		vertexAttributes[0].buffer_slot = 0;
		vertexAttributes[0].format = SDL_GPU_VERTEXELEMENTFORMAT_FLOAT4;
		vertexAttributes[0].offset = offsetof(SimpleShape::Vertex, position);
		vertexAttributes[1].location = 1;
		vertexAttributes[1].buffer_slot = 0;
		vertexAttributes[1].format = SDL_GPU_VERTEXELEMENTFORMAT_FLOAT4;
		vertexAttributes[1].offset = offsetof(SimpleShape::Vertex, normal);

		SDL_GPUVertexInputState vertexInputState {};
		vertexInputState.vertex_buffer_descriptions = &vertexBufferDesc;
		vertexInputState.num_vertex_buffers = 1;
		vertexInputState.vertex_attributes = vertexAttributes;
		vertexInputState.num_vertex_attributes = 2;

		// Depth-stencil state: match the framework's D32_FLOAT depth target.
		SDL_GPUDepthStencilState depthStencilState {};
		depthStencilState.enable_depth_test = true;
		depthStencilState.enable_depth_write = true;
		depthStencilState.compare_op = SDL_GPU_COMPAREOP_LESS;

		// Color target matching the effective scene format.
		SDL_GPUColorTargetDescription colorTarget {};
		colorTarget.format = player.mainRenderTargetInfo()->colorFormat;

		SDL_GPUGraphicsPipelineTargetInfo targetInfo {};
		targetInfo.color_target_descriptions = &colorTarget;
		targetInfo.num_color_targets = 1;
		targetInfo.has_depth_stencil_target = true;
		targetInfo.depth_stencil_format = SDL_GPU_TEXTUREFORMAT_D32_FLOAT;

		SDL_GPUGraphicsPipelineCreateInfo pipelineInfo {};
		pipelineInfo.vertex_shader = vertexShader;
		pipelineInfo.fragment_shader = fragmentShader;
		pipelineInfo.vertex_input_state = vertexInputState;
		pipelineInfo.primitive_type = SDL_GPU_PRIMITIVETYPE_TRIANGLELIST;
		pipelineInfo.depth_stencil_state = depthStencilState;
		pipelineInfo.target_info = targetInfo;

		m_pipeline = SDL_CreateGPUGraphicsPipeline(device.handle(), &pipelineInfo);
		if (!m_pipeline) {
			SDL_LogCritical(SDL_LOG_CATEGORY_ERROR, "Creating the pipeline failed: %s", SDL_GetError());
		}

		// The pipeline has its own references to the shader objects now.
		SDL_ReleaseGPUShader(device.handle(), vertexShader);
		SDL_ReleaseGPUShader(device.handle(), fragmentShader);
	}

	/// Does nothing, as the applet holds no viewport-dependent resources.
	void onViewportResize (fcg::Device &device, const glm::uvec2 &oldViewportSize, fcg::Player &player) override {
		// Nothing to do.
	}

	/// \brief Shows shape, display mode, line appearance and corner sphere controls.
	///
	/// \param device The application's GPU device.
	/// \param player The player supplying GUI layout and scaling information.
	void gui (fcg::Device &device, fcg::Player &player) override
	{
		// Start our widget
		const auto &workPos = ImGui::GetMainViewport()->WorkPos,
		           &padding = ImGui::GetStyle().WindowPadding;
		const auto workSizeX = ImGui::GetMainViewport()->WorkSize.x;
		const auto initialWidth = player.toGuiUnits(264.f);
		ImGui::SetNextWindowSize({ initialWidth, 0 }, ImGuiCond_FirstUseEver);
		ImGui::SetNextWindowPos(
			ImVec2{workSizeX-initialWidth - padding.x, workPos.y + padding.y}, ImGuiCond_FirstUseEver
		);
		ImGui::Begin("Simple Shapes");

		// Shape selection combo box.
		if (ImGui::BeginCombo("Shape", shapes[selectedShape]->name()))
		{
			for (unsigned i=0; i<(unsigned)SS::NUM; ++i) {
				const bool isSelected = (i == static_cast<std::size_t>(selectedShape));
				if (ImGui::Selectable(shapes[i]->name(), isSelected)) {
					selectedShape = static_cast<int>(i);
					player.requireSceneRedraw();
				}
				if (isSelected)
					ImGui::SetItemDefaultFocus();
			}
			ImGui::EndCombo();
		}

		ImGui::Separator();

		// GUI for the currently selected shape's parameters.
		shapes[selectedShape]->gui();

		// Choose the representation without changing the underlying shape geometry
		ImGui::Separator();
		constexpr const char *displayNames[]{"Solid", "Wireframe", "Triangulated wireframe"};
		ImGui::SetNextItemWidth(-ImGui::CalcTextSize("Display").x - ImGui::GetStyle().ItemInnerSpacing.x);
		if (ImGui::BeginCombo("Display", displayNames[(std::size_t)displayMode]))
		{
			for (unsigned i = 0; i < 3; ++i)
			{
				const bool selected = i == (unsigned)displayMode;
				if (ImGui::Selectable(displayNames[i], selected)) {
					displayMode = (DisplayMode)i;
					player.requireSceneRedraw();
				}
				if (selected)
					ImGui::SetItemDefaultFocus();
			}
			ImGui::EndCombo();
		}
		ImGui::BeginDisabled(displayMode == DisplayMode::Solid);
		ImGui::SetNextItemWidth(-ImGui::CalcTextSize("Line width (px)").x - ImGui::GetStyle().ItemInnerSpacing.x);
		bool lineStyleChanged = ImGui::SliderFloat("Line width (px)", &lineWidth, 1.f, 10.f, "%.1f",
			ImGuiSliderFlags_AlwaysClamp);
		ImGui::SetItemTooltip("Full face-edge width in physical framebuffer pixels; triangulation diagonals use 75%%.");
		if (lineStyleChanged) {
			wireRadiiDirty = true;
			wireReady = false;
		}
		lineStyleChanged |= ImGui::Checkbox("Anti-aliasing", &lineAntialiasing);
		ImGui::EndDisabled();
		if (lineStyleChanged) {
			applyLineStyle();
			player.requireSceneRedraw();
		}

		// Configure corner markers independently of the selected shape's parameters
		ImGui::Separator();
		if (ImGui::Checkbox("Show corners", &showCorners))
			player.requireSceneRedraw();
		ImGui::BeginDisabled(!showCorners);
		ImGui::SetNextItemWidth(-ImGui::CalcTextSize("Corner radius (%)").x - ImGui::GetStyle().ItemInnerSpacing.x);
		if (ImGui::SliderFloat("Corner radius (%)", &cornerRadiusPercent, .1f, 25.f, "%.1f%%",
			ImGuiSliderFlags_AlwaysClamp))
			cornerRadiusDirty = true;
		ImGui::SetItemTooltip("Sphere radius as a percentage of the shape's circumradius.");
		ImGui::SetNextItemWidth(-ImGui::CalcTextSize("Corner color").x - ImGui::GetStyle().ItemInnerSpacing.x);
		if (ImGui::ColorEdit3("Corner color", &cornerColor.x))
			cornerColorDirty = true;
		ImGui::EndDisabled();

		ImGui::End();
	}

	/// \brief Update the mesh and independently refresh enabled corner and wireframe data.
	///
	/// \param device The device on which to upload mesh and corner data.
	/// \param player The application's player.
	/// \param dt The elapsed time since the preceding update, in seconds.
	void update (fcg::Device &device, fcg::Player &player, float dt) override
	{
		// Invalidate both visualization caches, including when their display modes are hidden
		auto &shape = *shapes[selectedShape];
		if (cachedShape != &shape || shape.dirty())
		{
			cachedShape = &shape;
			cornerPositionsDirty = true;
			cornersReady = false;
			wireGeometryDirty = true;
			wireReady = false;
			player.requireSceneRedraw();
		}
		shape.update(device);
		if (shape.dirty() || !shape.numIndices())
			return;

		// Refresh each visualization independently after the mesh's upload succeeds
		if (displayMode != DisplayMode::Solid && (wireGeometryDirty || wireRadiiDirty))
			updateWireframe(shape, player);
		if (showCorners && (cornerPositionsDirty || cornerRadiusDirty || cornerColorDirty))
			updateCorners(shape, player);
	}

	/// \brief
	/// 	Draw the selected representation and enabled corner spheres with the current camera.
	///
	/// \param device The device shared by the pipelines and active render pass.
	/// \param rs The current camera's viewing transformations.
	/// \param renderPass The active scene pass compatible with the pipelines.
	/// \param commandBuffer The command buffer containing the active render pass.
	/// \param player The application's player.
	void render (
		fcg::Device &device, fcg::RenderState &rs, SDL_GPURenderPass *renderPass,
		SDL_GPUCommandBuffer *commandBuffer, fcg::Player &player
	) override
	{
		const auto &shape = *shapes[selectedShape];
		if (!shape.numIndices())
			return;

		// The solid representation contributes surface depth before drawing its markers
		if (displayMode == DisplayMode::Solid && m_pipeline)
			drawMesh(shape, rs, renderPass, commandBuffer);

		// Corner spheres occlude wire segments behind them in either wireframe representation
		if (showCorners && cornersReady && cornerRenderer)
		{
			fcg::DrawOptions options;
			options.lighting.enabled = true;
			options.lighting.direction = glm::vec3(1.f / 3.f, 1.f / 3.f, 1.f);
			if (auto result = cornerRenderer->draw(
				*cornerAttributes, rs, commandBuffer, renderPass, options
			); !result)
				SDL_LogError(
					SDL_LOG_CATEGORY_APPLICATION, "Drawing corner spheres: %s", result.error().message.c_str()
				);
		}

		// Select the face-edge suffix or draw all segments with face edges blending over diagonals
		if (displayMode != DisplayMode::Solid && wireReady && lineRenderer)
		{
			const fcg::InstanceRange range{
				.first = displayMode == DisplayMode::Wireframe ? wireDiagonalCount : 0
			};
			if (auto result = lineRenderer->draw(
				*wireAttributes, *wireEdges, rs, commandBuffer, renderPass, {}, range
			); !result)
				SDL_LogError(SDL_LOG_CATEGORY_APPLICATION, "Drawing wireframe: %s", result.error().message.c_str());
		}
	}


protected:

	////
	// Methods

	/// Copy the current filtering choice to the available line renderer.
	void applyLineStyle () {
		if (lineRenderer)
			lineRenderer->setStyle({.filter = lineAntialiasing
				? fcg::LineFilter::Smoothstep : fcg::LineFilter::None});
	}

	/// \brief Refresh wireframe geometry or pixel radii after a successful mesh upload.
	///
	/// \param shape The selected, successfully uploaded shape.
	/// \param player The player whose scene is refreshed after updates or failures.
	void updateWireframe (const SimpleShape &shape, fcg::Player &player)
	{
		// Give each geometric corner separate attributes for diagonals and face boundaries
		const auto corners = shape.corners();
		std::vector<glm::vec4> positions, colors;
		std::vector<std::uint32_t> indices;
		auto diagonalCount = wireDiagonalCount;
		if (wireGeometryDirty)
		{
			positions.reserve(2 * corners.size());
			positions.insert(positions.end(), corners.begin(), corners.end());
			positions.insert(positions.end(), corners.begin(), corners.end());
			colors.assign(corners.size(), glm::vec4(1/3.f, 1/3.f, 1/3.f, 1.f));
			colors.resize(2 * corners.size(), glm::vec4(1.f));

			// Put diagonals first so the regular face edges blend over them in the same draw
			indices = shape.triangulationDiagonals();
			diagonalCount = indices.size() / 2;
			indices.reserve(indices.size() + shape.edges().size());
			for (const auto corner : shape.edges())
				indices.push_back((std::uint32_t)corners.size() + corner);
		}

		// Width edits replace only the explicit half-widths, keeping geometry and colors in place
		std::vector<float> radii(corners.size(), lineWidth * .25f);
		radii.resize(2 * corners.size(), lineWidth * 2/3.f);
		auto result = wireAttributes->setAttributes([&] (fcg::PrimitiveAttributes::Update &attributes)
		{
			if (wireGeometryDirty) {
				attributes.set<fcg::Attribute::Position>(std::span(positions));
				attributes.set<fcg::Attribute::Color>(std::span(colors));
			}
			attributes.set<fcg::Attribute::Radius>(std::span(radii));
		});
		if (result && wireGeometryDirty)
			result = wireEdges->setIndices(indices);
		if (!result) {
			wireReady = false;
			SDL_LogError(SDL_LOG_CATEGORY_APPLICATION, "Updating wireframe: %s", result.error().message.c_str());
			player.requireSceneRedraw();
			return;
		}

		// Make both representations drawable only after every upload succeeds
		wireDiagonalCount = diagonalCount;
		wireGeometryDirty = false;
		wireRadiiDirty = false;
		wireReady = true;
		player.requireSceneRedraw();
	}

	/// \brief Refresh visible corner markers independently of wireframe readiness.
	///
	/// \param shape The selected, successfully uploaded shape.
	/// \param player The player whose scene is refreshed after updates or failures.
	void updateCorners (const SimpleShape &shape, fcg::Player &player)
	{
		// Measure the generated corners only when their positions change
		float circumradius = cornerCircumradius;
		if (cornerPositionsDirty) {
			circumradius = 0.f;
			for (const auto &position : shape.corners())
				circumradius = std::max(circumradius, glm::length(glm::vec3(position) / position.w));
		}

		// Use shared constants for corner size and color edits
		auto result = cornerAttributes->setAttributes([&] (fcg::PrimitiveAttributes::Update &attributes)
		{
			if (cornerPositionsDirty)
				attributes.set<fcg::Attribute::Position>(shape.corners());
			if (cornerPositionsDirty || cornerColorDirty)
				attributes.set<fcg::Attribute::Color>(glm::vec4(cornerColor, 1.f));
			if (cornerPositionsDirty || cornerRadiusDirty)
				attributes.set<fcg::Attribute::Extent>(glm::vec3(cornerRadiusPercent / 100.f * circumradius));
		});
		if (!result) {
			cornersReady = false;
			SDL_LogError(SDL_LOG_CATEGORY_APPLICATION, "Updating corner spheres: %s", result.error().message.c_str());
			player.requireSceneRedraw();
			return;
		}

		// Publish marker state after the complete attribute update succeeds
		cornerCircumradius = circumradius;
		cornerPositionsDirty = false;
		cornerRadiusDirty = false;
		cornerColorDirty = false;
		cornersReady = true;
		player.requireSceneRedraw();
	}

	/// \brief Draw the filled mesh using its successfully uploaded vertex and index buffers.
	///
	/// \param shape The shape whose GPU geometry is available.
	/// \param state The current viewing transformation.
	/// \param pass The active scene render pass.
	/// \param command The command buffer containing the pass.
	void drawMesh (
		const SimpleShape &shape, fcg::RenderState &state, SDL_GPURenderPass *pass, SDL_GPUCommandBuffer *command
	)
	{
		// Install the mesh pipeline and its viewing transformation
		SDL_BindGPUGraphicsPipeline(pass, m_pipeline);
		state.pushViewingUniforms(command, fcg::ShaderStage::VERTEX, 0);
		auto vertex = shape.vertexBuffer()->bindVertex(pass);
		auto index = shape.indexBuffer()->bindIndex(pass, SDL_GPU_INDEXELEMENTSIZE_32BIT);
		if (!vertex || !index) {
			const auto &error = !vertex ? vertex.error() : index.error();
			SDL_LogError(SDL_LOG_CATEGORY_APPLICATION, "Binding geometry: %s", error.message.c_str());
			return;
		}
		SDL_DrawGPUIndexedPrimitives(pass, shape.numIndices(), 1, 0, 0, 0);
	}


	////
	// Fields

	/// One instance of each simple shape, indexed by <tt>\ref SimpleShapes "SimpleShapes"</tt>.
	std::unique_ptr<SimpleShape> shapes[(size_t)SS::NUM];

	/// The index of the currently selected shape in <tt>\ref shapes "shapes"</tt>.
	int selectedShape = 1;

	/// The device passed to \c init, kept so that the destructor can release the pipeline.
	fcg::Device *m_device = nullptr;

	/// The graphics pipeline used to render the simple shapes, or \c nullptr if its creation failed.
	SDL_GPUGraphicsPipeline *m_pipeline = nullptr;

	/// The corner sphere renderer for the effective scene target, empty if creation failed.
	std::optional<fcg::EllipsoidRenderer> cornerRenderer;

	/// Owned sphere positions and shared color and extent values on the applet's device.
	std::unique_ptr<fcg::PrimitiveAttributes> cornerAttributes;

	/// The wireframe renderer for the current scene format, empty if creation failed.
	std::optional<fcg::LineRenderer> lineRenderer;

	/// Two copies of the corners with explicit light-grey diagonal and white face-edge attributes.
	std::unique_ptr<fcg::PrimitiveAttributes> wireAttributes;

	/// Unique diagonal pairs followed by geometric boundary pairs, referencing their respective corner copies.
	std::unique_ptr<fcg::PrimitiveConnectivity> wireEdges;

	/// Number of leading diagonal segments in the successfully uploaded connectivity.
	std::size_t wireDiagonalCount = 0;

	/// The selected shape representation.
	DisplayMode displayMode = DisplayMode::Solid;

	/// Full face-edge width in physical framebuffer pixels; diagonals use 75% of this width.
	float lineWidth = 1.5f;

	/// Whether line boundaries use smooth filtering.
	bool lineAntialiasing = true;

	/// Whether the selected shape's wireframe data needs uploading.
	bool wireGeometryDirty = true;

	/// Whether the explicit pixel radii need uploading after a width edit.
	bool wireRadiiDirty = true;

	/// Whether attributes and connectivity match the selected uploaded mesh and requested line width.
	bool wireReady = false;

	/// Whether the GUI enables drawing corner spheres.
	bool showCorners = false;

	/// The sphere radius as a percentage of the selected shape's circumradius.
	float cornerRadiusPercent = 2.5f;

	/// The shared RGB color of the opaque corner spheres.
	glm::vec3 cornerColor{1.f, .65f, .1f};

	/// The shape whose geometry is being tracked for corner and wireframe updates.
	const SimpleShape *cachedShape = nullptr;

	/// Whether corner positions need uploading after a shape selection or geometry change.
	bool cornerPositionsDirty = true;

	/// Whether the shared sphere extent needs updating after a radius edit.
	bool cornerRadiusDirty = true;

	/// Whether the shared sphere color needs updating after a color edit.
	bool cornerColorDirty = true;

	/// Whether the marker attributes match the successfully uploaded selected mesh and requested radius and color.
	bool cornersReady = false;

	/// The object-space circumradius associated with the uploaded corner positions.
	float cornerCircumradius = 0.f;
};



//////
//
// Function implementations
//

/// The program entry point. Runs an orbit camera followed by the simple shapes applet in a window titled
/// <tt>"Hello FCG!"</tt>.
int main () {
	// Run with our demo applets
	return fcg::run<fcg::applet::OrbitCamera, SimpleShapesApplet>(
		fcg::PlayerSettings{.mainWindowTitle="Hello FCG!"}
	);
}
